import { showAlert } from "../notification_control.js";
import { cancelSQL, checkQueryStatus, querySQL } from "../query.js";
import { createTabControl } from "../tabs.js";
import { getExplain } from "../tree_context_functions/tree_postgresql.js";
import { buildSnippetContextMenuObjects } from "../tree_context_functions/tree_snippets.js";
import {
	adjustQueryTabObjects,
	indentSQL,
	removeTab,
	renameTab,
	resizeVertical,
	showMenuNewTab,
	toggleExpandToPanelView,
	toggleExplainContext,
	uiCopyTextToClipboard,
} from "../workspace.js";


export var v_createQueryTabFunction = function (p_table, p_tab_db_id) {
	// Removing last tab of the inner tab list.
	v_connTabControl.selectedTab.tag.tabControl.removeLastTab();

	// Updating inner tab_name.
	var v_name = "Query";
	if (p_table) {
		v_name = p_table;
	}
	let v_name_html =
		'<span id="tab_title">' +
		v_name +
		"</span>" +
		'<span id="tab_loading" style="visibility:hidden;">' +
		'<i class="tab-icon node-spin"></i>' +
		"</span>" +
		'<i title="" id="tab_check" style="display: none;" class="fas fa-check-circle tab-icon icon-check"></i>';

	// Creating console tab in the inner tab list.
	var v_tab = v_connTabControl.selectedTab.tag.tabControl.createTab({
		p_name: v_name_html,
		p_selectFunction: function () {
			if (this.tag != null) {
				this.tag.resize();
			}
			if (this.tag != null && this.tag.editor != null) {
				this.tag.editor.focus();
				checkQueryStatus(this);
			}
		},
		p_closeFunction: function (e, p_tab) {
			var v_current_tab = p_tab;
			beforeCloseTab(e, function () {
				removeTab(v_current_tab);
			});
		},
		p_dblClickFunction: renameTab,
	});

	// Selecting newly created tab.
	v_connTabControl.selectedTab.tag.tabControl.selectTab(v_tab);

	// Adding unique names to spans.
	var v_tab_title_span = /** @type {HTMLElement} */ (document.getElementById("tab_title"));
	v_tab_title_span.id = "tab_title_" + v_tab.id;
	var v_tab_loading_span = /** @type {HTMLElement} */ (document.getElementById("tab_loading"));
	v_tab_loading_span.id = "tab_loading_" + v_tab.id;
	var v_tab_check_span = /** @type {HTMLElement} */ (document.getElementById("tab_check"));
	v_tab_check_span.id = "tab_check_" + v_tab.id;

	// Creating the template for the command_history_modal.
	var command_history_modal =
		"<div class='modal fade' id='modal_command_history_" +
		v_tab.id +
		"' tabindex='-1' role='dialog' aria-hidden='true'>" +
		"<div class='modal-dialog modal-xl' role='document'>" +
		"<div class='modal-content'>" +
		"<div class='modal-header'>" +
		"<h5 class='modal-title'>" +
		"Command history" +
		"</h5>" +
		"<button id='bt_close_command_history_" +
		v_tab.id +
		"' type='button' class='close' data-dismiss='modal' aria-label='Close'>" +
		"<span aria-hidden='true'>&times;</span>" +
		"</button>" +
		"</div>" +
		"<div class='modal-body'>" +
		"<div id='command_history_div_" +
		v_tab.id +
		"' class='query_command_history'>" +
		"<div id='command_history_header_" +
		v_tab.id +
		"' class='query_command_history_header'></div>" +
		"<div id='command_history_grid_" +
		v_tab.id +
		"' class='query_command_history_grid' style='width: 100%; height: calc(100vh - 16.5rem); overflow: hidden;'></div>" +
		"</div>" +
		"</div>" +
		"</div>" +
		"</div>" +
		"</div>";

	// Creating the template for the inner_query_tab.
	var v_html =
		'<div id="txt_query_' +
		v_tab.id +
		'" style="width: 100%; height: 200px;"></div>' +
		'<div id="query_resize_line_' +
		v_tab.id +
		'" class="omnidb__resize-line__container" style="width: 100%; height: 5px; cursor: ns-resize;"><div class="resize_line_horizontal" style="height: 0px; border-bottom: 1px dashed #acc4e8;"></div><div style="height:5px;"></div></div>' +
		command_history_modal +
		'<div class="row mb-1">' +
		'<div class="tab_actions omnidb__tab-actions col-12">' +
		'<button id="bt_start_' +
		v_tab.id +
		'" class="btn btn-sm omnidb__theme__btn--primary omnidb__tab-actions__btn" title="Run"><i class="fas fa-play fa-light"></i></button>' +
		'<button id="bt_indent_' +
		v_tab.id +
		'" class="btn btn-sm omnidb__theme__btn--secondary omnidb__tab-actions__btn" title="Indent SQL"><i class="fas fa-indent fa-light"></i></button>' +
		'<button id="bt_history_' +
		v_tab.id +
		'" class="btn btn-sm omnidb__theme__btn--secondary omnidb__tab-actions__btn" title="Command History"><i class="fas fa-list fa-light"></i></button>' +
		'<button id="bt_explain_' +
		v_tab.id +
		'" class="dbms_object postgresql_object btn btn-sm omnidb__theme__btn--secondary omnidb__tab-actions__btn" title="Explain" style="display: none;"><i class="fas fa-search fa-light"></i></button>' +
		'<button id="bt_analyze_' +
		v_tab.id +
		'" class="dbms_object postgresql_object btn btn-sm omnidb__theme__btn--secondary omnidb__tab-actions__btn" title="Explain Analyze" style="display: none;"><i class="fas fa-search-plus fa-light"></i></button>' +
		'<div class="dbms_object postgresql_object omnidb__form-check form-check form-check-inline"><input id="check_autocommit_' +
		v_tab.id +
		'" class="form-check-input" type="checkbox" checked="checked"><label class="form-check-label dbms_object postgresql_object custom_checkbox query_info" for="check_autocommit_' +
		v_tab.id +
		'">Autocommit</label></div>' +
		'<div class="dbms_object postgresql_object omnidb__tab-status"><i id="query_tab_status_' +
		v_tab.id +
		'" title="Not connected" class="fas fa-dot-circle tab-status tab-status-closed dbms_object postgresql_object omnidb__tab-status__icon"></i><span id="query_tab_status_text_' +
		v_tab.id +
		'" title="Not connected" class="tab-status-text query_info dbms_object postgresql_object ms-1">Not connected</span></div>' +
		'<button id="bt_fetch_more_' +
		v_tab.id +
		'" class="btn btn-sm omnidb__theme__btn--secondary omnidb__tab-actions__btn" title="Run" style="display: none;">Fetch more</button>' +
		'<button id="bt_fetch_all_' +
		v_tab.id +
		'" class="btn btn-sm omnidb__theme__btn--secondary omnidb__tab-actions__btn" title="Run" style="display: none;">Fetch all</button>' +
		'<button id="bt_commit_' +
		v_tab.id +
		'" class="dbms_object dbms_object_hidden postgresql_object btn btn-sm omnidb__theme__btn--primary omnidb__tab-actions__btn" title="Run" style="display: none;">Commit</button>' +
		'<button id="bt_rollback_' +
		v_tab.id +
		'" class="dbms_object dbms_object_hidden postgresql_object btn btn-sm omnidb__theme__btn--secondary omnidb__tab-actions__btn" title="Run" style="display: none;">Rollback</button>' +
		'<button id="bt_cancel_' +
		v_tab.id +
		'" class="btn btn-sm btn-danger omnidb__tab-actions__btn" title="Cancel" style="display: none;">Cancel</button>' +
		'<div id="div_query_info_' +
		v_tab.id +
		'" class="omnidb__query-info"></div>' +
		'<button id="bt_export_' +
		v_tab.id +
		'" class="btn btn-sm omnidb__theme__btn--primary omnidb__tab-actions__btn ms-auto" title="Export Data"><i class="far fa-file fa-light"></i></button>' +
		'<select id="sel_export_type_' +
		v_tab.id +
		'" class="form-control omnidb__tab-actions__select" style="width: 80px;"><option selected="selected" value="csv">CSV</option><option value="tsv">TSV</option><option value="xlsx">XLSX</option><option value="json">JSON</option><option value="xml">XML</option><option value="md">Markdown</option></select>' +
		"</div>" +
		"</div>" +
		'<div id="query_result_tabs_container' +
		v_tab.id +
		'" class="omnidb__query-result-tabs">' +
		'<div style="position:absolute;top:0.25rem;right:2.75rem;">' +
		'<div class="omnidb__switch--explain omnidb__switch--explain--sm float-end me-1" data-bs-toggle="tooltip" data-bs-placement="left" data-bs-html="true" title="" data-bs-original-title="<h5>Toggle explain component.</h5><div>Switch between old and new explain visualizer (experimental).</div>">' +
		'<input id="explainContextToggler' +
		v_tab.id +
		'" type="checkbox" class="omnidb__switch--explain--input">' +
		'<label for="explainContextToggler' +
		v_tab.id +
		'" class="omnidb__switch--explain--label">' +
		'<span><i class="fas fa-th"></i></span>' +
		"</label>" +
		"</div>" +
		"</div>" +
		'<button id="bt_expand_query_result_' +
		v_tab.id +
		'" style="position:absolute;top:0.25rem;right:0.25rem;" type="button" class="btn btn-sm omnidb__theme__btn--secondary"><i class="fas fa-expand"></i></button>' +
		'<div id="query_result_tabs_' +
		v_tab.id +
		'">' +
		"</div>" +
		"</div>";

	// Updating the html.
	v_tab.elementDiv.innerHTML = v_html;

	// Creating tab list at the bottom of the query tab.
	var v_curr_tabs = createTabControl({ p_div: "query_result_tabs_" + v_tab.id });

	// Tab selection callback for `data` tab.
	var v_selectDataTabFunc = function () {
		v_curr_tabs.selectTabIndex(0);
		v_connTabControl.selectedTab.tag.tabControl.selectedTab.tag.currQueryTab = "data";
		v_tab.tag.resize();
	};

	// Tab selection callback for `message` tab.
	var v_selectMessageTabFunc = function () {
		v_curr_tabs.selectTabIndex(1);
		v_tag.currQueryTab = "message";
		v_connTabControl.selectedTab.tag.tabControl.selectedTab.tag.div_count_notices.style.display = "none";
		v_tab.tag.resize();
	};

	// Tab selection callback for `explain` tab.
	var v_selectExplainTabFunc = function () {
		v_curr_tabs.selectTabIndex(2);
		v_connTabControl.selectedTab.tag.tabControl.selectedTab.tag.currQueryTab = "explain";
		v_tab.tag.resize();
		// Loads or Updates all tooltips.
		$('[data-bs-toggle="tooltip"]').tooltip({ animation: true, html: true });
	};

	// Creating the `data` tab.
	var v_data_tab = v_curr_tabs.createTab({
		p_name: "Data",
		p_close: false,
		p_clickFunction: function (e) {
			v_selectDataTabFunc();
		},
	});
	v_data_tab.elementDiv.innerHTML =
		"<div class='p-2 omnidb__query-result-tabs__content omnidb__theme-border--primary'>" +
		"<div id='div_result_" +
		v_tab.id +
		"' class='omnidb__query-result-tabs__content' style='width: 100%; overflow: hidden;'></div>" +
		"</div>";

	// Creating the `message` tab.
	var v_messages_tab = v_curr_tabs.createTab({
		p_name:
			"Messages <div id='query_result_tabs_count_notices_" +
			v_tab.id +
			"' class='count_notices' style='display: none;'></div>",
		p_close: false,
		p_clickFunction: function (e) {
			v_selectMessageTabFunc();
		},
	});
	v_messages_tab.elementDiv.innerHTML =
		"<div class='p-2 omnidb__query-result-tabs__content omnidb__theme-border--primary'>" +
		"<div id='div_notices_" +
		v_tab.id +
		"' class='omnidb__query-result-tabs__content' style='width: 100%; overflow: hidden;'></div>" +
		"</div>";
	v_messages_tab.elementA.classList.add("dbms_object");
	v_messages_tab.elementA.classList.add("postgresql_object");

	// Creating the `explain` tab.
	var v_explain_tab = v_curr_tabs.createTab({
		p_name: "Explain",
		p_close: false,
		p_clickFunction: function (e) {
			v_selectExplainTabFunc();
		},
	});
	v_explain_tab.elementDiv.innerHTML =
		"<div class='p-2 omnidb__query-result-tabs__content omnidb__theme-border--primary'>" +
		"<div id='div_explain_default" +
		v_tab.id +
		"' class='omnidb__query-result-tabs__content omnidb__query-result-tabs__content--explain-default' style='width: 100%; overflow: auto;'></div>" +
		"<div id='div_explain_" +
		v_tab.id +
		"' class='omnidb__query-result-tabs__content omnidb__query-result-tabs__content--explain-legere' style='width: 100%; overflow: hidden;'></div>" +
		"</div>";
	v_explain_tab.elementA.classList.add("dbms_object");
	v_explain_tab.elementA.classList.add("postgresql_object");

	// Creating the editor for `query`.
	var langTools = ace.require("ace/ext/language_tools");
	var v_editor = ace.edit("txt_query_" + v_tab.id);
	v_editor.$blockScrolling = Infinity;
	v_editor.setTheme("ace/theme/" + v_editor_theme);
	v_editor.session.setMode("ace/mode/sql");
	v_editor.setFontSize(Number(v_font_size));
	v_editor.session.setTabSize(v_indent_size || 4);
	v_editor.session.setUseSoftTabs(v_indent_char !== 'tab');

	// Setting custom keyboard shortcuts callbacks.
	$("#txt_query_" + v_tab.id)
		.find(".ace_text-input")
		.on("keyup", function (event) {
			if (v_connTabControl.selectedTab.tag.enable_autocomplete !== false) {
				autocomplete_start(v_editor, 0, event);
			}
		});
	$("#txt_query_" + v_tab.id)
		.find(".ace_text-input")
		.on("keydown", function (event) {
			if (v_connTabControl.selectedTab.tag.enable_autocomplete !== false) {
				autocomplete_keydown(v_editor, event);
			} else {
				autocomplete_update_editor_cursor(v_editor, event);
			}
		});

	/** @type {HTMLElement} */ (document.getElementById("txt_query_" + v_tab.id)).addEventListener("contextmenu", function (event) {
		event.stopPropagation();
		event.preventDefault();

		var v_option_list = [
			{
				text: "Copy",
				icon: "fas cm-all fa-terminal",
				action: function () {
					// Getting the value
					var copy_text = v_editor.getValue();
					// Calling copy to clipboard.
					uiCopyTextToClipboard(copy_text);
				},
			},
			{
				text: "Save as snippet",
				icon: "fas cm-all fa-save",
				submenu: {
					elements: buildSnippetContextMenuObjects("save", v_connTabControl.tag.globalSnippets, v_editor),
				},
			},
		];

		if (v_connTabControl.tag.globalSnippets.files.length != 0 || v_connTabControl.tag.globalSnippets.folders.length != 0)
			v_option_list.push({
				text: "Use snippet",
				icon: "fas cm-all fa-book",
				submenu: {
					elements: buildSnippetContextMenuObjects("load", v_connTabControl.tag.globalSnippets, v_editor),
				},
			});
		customMenu(
			{
				x: event.clientX + 5,
				y: event.clientY + 5,
			},
			v_option_list,
			null,
		);
	});

	// Remove shortcuts from ace in order to avoid conflict with omnidb shortcuts
	v_editor.commands.bindKey("ctrl-space", null);
	v_editor.commands.bindKey("alt-e", null);
	v_editor.commands.bindKey("Cmd-,", null);
	v_editor.commands.bindKey("Ctrl-,", null);
	v_editor.commands.bindKey("Cmd-Delete", null);
	v_editor.commands.bindKey("Ctrl-Delete", null);
	v_editor.commands.bindKey("Ctrl-Up", null);
	v_editor.commands.bindKey("Ctrl-Down", null);
	v_editor.commands.bindKey("Up", null);
	v_editor.commands.bindKey("Down", null);
	v_editor.commands.bindKey("Tab", null);

	// Setting the autofocus for the editor component.
	/** @type {HTMLElement} */ (document.getElementById("txt_query_" + v_tab.id)).onclick = function () {
		v_editor.focus();
	};

	// Updating the tab_db_id.
	var v_tab_db_id = null;
	if (p_tab_db_id) {
		v_tab_db_id = p_tab_db_id;
	}

	// Creating the exportData action for the tab.
	//
	// Runs the export query on the backend (so it covers the full result
	// set, not just whatever page is currently rendered in the grid, and
	// picks up the user's CSV delimiter/encoding settings). In the desktop
	// app, asks /export_save_dialog/ to relay a native "Save As" for the
	// resulting temp file to wails-app — that's a plain same-origin HTTP
	// hop rather than a direct Wails binding call (window.go/window.runtime),
	// because this page is loaded via a full top-level navigation to
	// go-server's own origin and never gets those injected (see
	// go-server/export_save_dialog.go's comment for the full story).
	// /export_save_dialog/ only exists at all when go-server is listening
	// on loopback (see main.go), which a network-accessible "-H" deployment
	// isn't — gv_desktopMode is false there (and in any other
	// browser/server access), so this falls back to the original browser
	// download-link behavior instead of hitting a 404.
	var v_export_data = function () {
		var v_exp_callback = function (p_data) {
			if (!gv_desktopMode) {
				v_connTabControl.selectedTab.tag.tabControl.selectedTab.tag.selectDataTabFunc();
				var v_text =
					'<div style="font-size: 14px;">The file is ready. <a class="link_text" href="' +
					p_data.v_data.v_filename +
					'" download="' +
					p_data.v_data.v_downloadname +
					'">Save</a></div>';
				v_connTabControl.selectedTab.tag.tabControl.selectedTab.tag.div_result.innerHTML = v_text;
				return;
			}

			fetch("/export_save_dialog/", {
				method: "POST",
				headers: { "Content-Type": "application/json" },
				body: JSON.stringify({
					v_filepath: p_data.v_data.v_filepath,
					v_downloadname: p_data.v_data.v_downloadname,
				}),
			})
				.then(function (p_response) {
					return p_response.json();
				})
				.then(function (p_result) {
					if (p_result.error) {
						showAlert("Error saving file: " + p_result.error);
					} else if (p_result.path) {
						showAlert("File exported to: " + p_result.path);
					}
				})
				.catch(function (p_error) {
					showAlert("Error saving file: " + p_error);
				});
		};

		var v_exp_query = v_connTabControl.selectedTab.tag.tabControl.selectedTab.tag.editor.getValue();
		var v_exp_type = v_connTabControl.selectedTab.tag.tabControl.selectedTab.tag.sel_export_type.value;
		querySQL(0, true, v_exp_query, v_exp_callback, true, v_exp_query, "export_" + v_exp_type, true);
	};

	var v_resizeFunction = function () {
		var v_tab_tag = v_connTabControl.selectedTab.tag.tabControl.selectedTab.tag;
		if (v_tab_tag.currQueryTab == "data") {
			v_tab_tag.div_result.style.height =
				window.innerHeight - $(v_tab_tag.div_result).offset().top - 1.25 * v_font_size + "px";
			setTimeout(function () {
				if (v_tab_tag.ht != null) {
					v_tab_tag.ht.render();
				}
				if (v_tab_tag.editor != null) {
					v_tab_tag.editor.resize();
				}
			}, 400);
		} else if (v_tab_tag.currQueryTab == "message") {
			v_tab_tag.div_notices.style.height =
				window.innerHeight - $(v_tab_tag.div_notices).offset().top - 1.25 * v_font_size + "px";
		} else if (v_tab_tag.currQueryTab == "explain") {
			v_tab_tag.div_explain_default.style.height =
				window.innerHeight - $(v_tab_tag.div_explain_default).offset().top - 1.25 * v_font_size + "px";
			v_tab_tag.div_explain.style.height =
				window.innerHeight - $(v_tab_tag.div_explain).offset().top - 1.25 * v_font_size + "px";
			setTimeout(function () {
				if (v_tab_tag.explainControl) {
					v_tab_tag.explainControl.resize();
				}
			}, 400);
		}
	};

	// Setting all tab_tag params.
	var v_tag = {
		tab_id: v_tab.id,
		mode: "query",
		editor: v_editor,
		editorDivId: "txt_query_" + v_tab.id,
		exportData: v_export_data,
		query_info: document.getElementById("div_query_info_" + v_tab.id),
		div_result: document.getElementById("div_result_" + v_tab.id),
		div_notices: document.getElementById("div_notices_" + v_tab.id),
		div_explain: document.getElementById("div_explain_" + v_tab.id),
		div_explain_default: document.getElementById("div_explain_default" + v_tab.id),
		div_count_notices: document.getElementById("query_result_tabs_count_notices_" + v_tab.id),
		sel_filtered_data: document.getElementById("sel_filtered_data_" + v_tab.id),
		sel_export_type: document.getElementById("sel_export_type_" + v_tab.id),
		tab_title_span: v_tab_title_span,
		tab_loading_span: v_tab_loading_span,
		tab_check_span: v_tab_check_span,
		query_tab_status: document.getElementById("query_tab_status_" + v_tab.id),
		query_tab_status_text: document.getElementById("query_tab_status_text_" + v_tab.id),
		bt_start: /** @type {HTMLElement} */ (document.getElementById("bt_start_" + v_tab.id)),
		bt_fetch_more: /** @type {HTMLElement} */ (document.getElementById("bt_fetch_more_" + v_tab.id)),
		bt_fetch_all: /** @type {HTMLElement} */ (document.getElementById("bt_fetch_all_" + v_tab.id)),
		bt_commit: /** @type {HTMLElement} */ (document.getElementById("bt_commit_" + v_tab.id)),
		bt_rollback: /** @type {HTMLElement} */ (document.getElementById("bt_rollback_" + v_tab.id)),
		bt_indent: /** @type {HTMLElement} */ (document.getElementById("bt_indent_" + v_tab.id)),
		bt_explain: /** @type {HTMLElement} */ (document.getElementById("bt_explain_" + v_tab.id)),
		bt_analyze: /** @type {HTMLElement} */ (document.getElementById("bt_analyze_" + v_tab.id)),
		bt_history: /** @type {HTMLElement} */ (document.getElementById("bt_history_" + v_tab.id)),
		bt_cancel: /** @type {HTMLElement} */ (document.getElementById("bt_cancel_" + v_tab.id)),
		bt_export: /** @type {HTMLElement} */ (document.getElementById("bt_export_" + v_tab.id)),
		check_autocommit: document.getElementById("check_autocommit_" + v_tab.id),
		resize: v_resizeFunction,
		state: 0,
		context: null,
		tabControl: v_connTabControl.selectedTab.tag.tabControl,
		queryTabControl: v_curr_tabs,
		/** @type {string|null} */
		currQueryTab: null,
		connTab: v_connTabControl.selectedTab,
		currDatabaseIndex: null,
		tab_db_id: v_tab_db_id,
		tempData: [],
		commandHistory: {
			modal: document.getElementById("modal_command_history_" + v_tab.id),
			div: document.getElementById("command_history_div_" + v_tab.id),
			headerDiv: document.getElementById("command_history_header_" + v_tab.id),
			gridDiv: document.getElementById("command_history_grid_" + v_tab.id),
			grid: null,
			currentPage: 1,
			pages: 1,
			spanNumPages: null,
			spanCurrPage: null,
			inputStartedFrom: null,
			inputStartedFromLastValue: null,
			inputStartedTo: null,
			inputStartedToLastValue: null,
			inputCommandContains: null,
			inputCommandContainsLastValue: null,
		},
	};

	// Setting the v_tab_tag.
	v_tab.tag = v_tag;
	v_tag.selectDataTabFunc = v_selectDataTabFunc;
	v_tag.selectMessageTabFunc = v_selectMessageTabFunc;
	v_tag.selectExplainTabFunc = v_selectExplainTabFunc;

	// Toolbar bindings. These replace the on*= attributes the buttons above used
	// to carry inside the HTML string, which were evaluated against the global
	// scope -- see dom_event_bindings.js and README.md.
	//
	// Each handler resolves the tab it acts on the same way it always did, from
	// v_connTabControl.selectedTab, rather than closing over v_tab: only the
	// selected tab's toolbar is on screen to be clicked, so the two are the same
	// element, and keeping the existing lookup keeps the behaviour identical.
	v_tag.bt_start.addEventListener("click", () => querySQL(0));
	v_tag.bt_fetch_more.addEventListener("click", () => querySQL(1));
	v_tag.bt_fetch_all.addEventListener("click", () => querySQL(2));
	v_tag.bt_commit.addEventListener("click", () => querySQL(3));
	v_tag.bt_rollback.addEventListener("click", () => querySQL(4));
	v_tag.bt_cancel.addEventListener("click", () => cancelSQL());
	v_tag.bt_indent.addEventListener("click", () => indentSQL());
	v_tag.bt_history.addEventListener("click", () => showCommandList());
	v_tag.bt_explain.addEventListener("click", () => getExplain(0));
	v_tag.bt_analyze.addEventListener("click", () => getExplain(1));
	// bt_export used to be looked up by an id no element carried, so this tag
	// entry was permanently null. The button has the id now.
	v_tag.bt_export.addEventListener("click", () => v_tag.exportData());
	/** @type {HTMLElement} */ (document.getElementById("bt_close_command_history_" + v_tab.id)).addEventListener(
		"click",
		() => closeCommandHistory(),
	);
	/** @type {HTMLElement} */ (document.getElementById("query_resize_line_" + v_tab.id)).addEventListener(
		"mousedown",
		(event) => resizeVertical(event),
	);
	/** @type {HTMLElement} */ (document.getElementById("explainContextToggler" + v_tab.id)).addEventListener(
		"click",
		() => toggleExplainContext(),
	);
	/** @type {HTMLElement} */ (document.getElementById("bt_expand_query_result_" + v_tab.id)).addEventListener(
		"click",
		() => toggleExpandToPanelView("query_result_tabs_container" + v_tab.id),
	);

	// Selecting the `data` tab by default.
	v_selectDataTabFunc();

	// Creating `Add` tab in the `inner_query` tab list
	var v_add_tab = v_connTabControl.selectedTab.tag.tabControl.createTab({
		p_name: "+",
		p_close: false,
		p_selectable: false,
		p_clickFunction: function (e) {
			showMenuNewTab(e);
		},
	});
	v_add_tab.tag = {
		mode: "add",
	};

	// Loads or Updates all tooltips.
	$('[data-bs-toggle="tooltip"]').tooltip({ animation: true, html: true });

	// Requesting an update on the workspace layout and sizes.
	setTimeout(function () {
		v_resizeFunction();
	}, 10);
	adjustQueryTabObjects(false);
	v_editor.focus();

	// Sets a render refresh for the grid on the commandHistory.modal after the modal is fully loaded
	$(v_connTabControl.selectedTab.tag.tabControl.selectedTab.tag.commandHistory.modal).on("shown.bs.modal", function () {
		v_connTabControl.selectedTab.tag.tabControl.selectedTab.tag.commandHistory.grid.render();
	});
};
